<?php require '../../../config/bootstrap.php';$u=require_auth();$p=db();$type=($_GET['type']??'expenses');$table=$type==='revenues'?'revenues':'expenses';if($_SERVER['REQUEST_METHOD']==='GET'){$s=$p->prepare("SELECT * FROM $table WHERE tenant_id=? ORDER BY id DESC LIMIT 100");$s->execute([$u['tenant_id']]);json_response(['data'=>$s->fetchAll()]);}require_role($u,['owner','admin','manager']);require_csrf();$d=request_json();foreach(['category','description','amount','date'] as $k)if(!array_key_exists($k,$d) || $d[$k]===null || $d[$k]==='')json_response(['error'=>"$k obrigatório"],422);$date=$d['date'];$s=$p->prepare("INSERT INTO $table(tenant_id,farm_id,category,description,amount,currency,".($table==='revenues'?'revenue_date':'expense_date').") VALUES(?,?,?,?,?,?,?)");$s->execute([$u['tenant_id'],$d['farm_id']??null,$d['category'],$d['description'],$d['amount'],$d['currency']??'MZN',$date]);$id=(int)$p->lastInsertId();audit($u,'create',$table,$id,['amount'=>$d['amount']]);json_response(['id'=>$id],201);
